import sys
import re
import argparse

class MelodyParser:
    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.variables = {}

    def error(self, message):
        print(f"Error: {message}", file=sys.stderr)
        sys.exit(65)

    def skip_whitespace(self):
        while self.pos < len(self.source):
            if self.source[self.pos].isspace():
                self.pos += 1
            elif self.source.startswith('//', self.pos):
                self.pos = self.source.find('\n', self.pos)
                if self.pos == -1:
                    self.pos = len(self.source)
            elif self.source.startswith('/*', self.pos):
                end_pos = self.source.find('*/', self.pos)
                if end_pos == -1:
                    self.error("unclosed comment")
                self.pos = end_pos + 2
            else:
                break

    def peek(self, length=1):
        return self.source[self.pos : self.pos + length]

    def consume(self, expected):
        if self.source.startswith(expected, self.pos):
            self.pos += len(expected)
            return True
        return False

    def expect(self, expected):
        if not self.consume(expected):
            self.error(f"expected {expected}")

    def parse_string(self):
        self.expect('"')
        res = ""
        while self.pos < len(self.source):
            char = self.source[self.pos]
            if char == '"':
                self.pos += 1
                return res
            if char == '\\':
                self.pos += 1
                if self.pos >= len(self.source): self.error("unclosed string")
                esc = self.source[self.pos]
                if esc == 'n': res += '\n'; self.pos += 1
                elif esc == 'r': res += '\r'; self.pos += 1
                elif esc == 't': res += '\t'; self.pos += 1
                elif esc == 'v': res += '\v'; self.pos += 1
                elif esc == 'f': res += '\f'; self.pos += 1
                elif esc == '0': res += '\0'; self.pos += 1
                elif esc == '\\': res += '\\'; self.pos += 1
                elif esc == '"': res += '"'; self.pos += 1
                elif esc == 'u':
                    self.pos += 1
                    hex_val = self.source[self.pos : self.pos + 4]
                    if len(hex_val) < 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_val):
                        self.error("invalid unicode escape")
                    res += '\\u' + hex_val
                    self.pos += 4
                else:
                    self.error("invalid escape sequence")
            else:
                res += char
                self.pos += 1
        self.error("unclosed string")

    def parse_symbol(self):
        self.expect('<')
        start = self.pos
        while self.pos < len(self.source) and self.source[self.pos] != '>':
            self.pos += 1
        name = self.source[start:self.pos]
        self.expect('>')
        symbols = {
            'char': '.', 'space': ' ', 'whitespace': r'\s', 'digit': r'\d', 'word': r'\w',
            'newline': r'\n', 'tab': r'\t', 'return': r'\r', 'vertical': r'\v', 'feed': r'\f',
            'boundary': r'\b', 'start': '^', 'end': '$', 'alphabetic': '[a-zA-Z]', 'alphanumeric': '[a-zA-Z0-9]',
        }
        if name not in symbols: self.error("usage of an unrecognized symbol")
        return symbols[name]

    def parse_raw(self):
        self.expect('`')
        start = self.pos
        while self.pos < len(self.source) and self.source[self.pos] != '`':
            self.pos += 1
        res = self.source[start:self.pos]
        self.expect('`')
        return res

    def escape_regex(self, s):
        res = ""
        for char in s:
            if char in r'.*+?()[]{}|\\^$': res += '\\' + char
            else: res += char
        return res

    def needs_grouping(self, regex):
        if len(regex) == 1: return False
        if len(regex) == 2 and regex[0] == '\\': return False
        if regex.startswith('[') and regex.endswith(']'):
            count = 0
            for i, c in enumerate(regex):
                if c == '[': count += 1
                elif c == ']': count -= 1
                if count == 0 and i < len(regex) - 1: return True
            return False
        if regex.startswith('(') and regex.endswith(')'):
            count = 0
            for i, c in enumerate(regex):
                if c == '(': count += 1
                elif c == ')': count -= 1
                if count == 0 and i < len(regex) - 1: return True
            return False
        return True

    def parse_expression(self, in_quantifier=False):
        self.skip_whitespace()
        if self.peek() == '"':
            regex = self.escape_regex(self.parse_string())
            return f"(?:{regex})" if in_quantifier and self.needs_grouping(regex) else regex
        elif self.peek() == '<':
            return self.parse_symbol()
        elif self.peek() == '`':
            regex = self.parse_raw()
            return f"(?:{regex})" if in_quantifier and self.needs_grouping(regex) else regex
        elif self.consume('match'):
            self.skip_whitespace(); self.expect('{')
            inner = self.parse_statements()
            self.expect('}')
            return f"(?:{inner})"
        elif self.consume('capture'):
            self.skip_whitespace()
            name = ""
            if self.peek() != '{':
                start = self.pos
                while self.pos < len(self.source) and not self.source[self.pos].isspace() and self.source[self.pos] != '{':
                    self.pos += 1
                name = self.source[start:self.pos]
                self.skip_whitespace()
            self.expect('{')
            inner = self.parse_statements()
            self.expect('}')
            return f"(?<{name}>{inner})" if name else f"({inner})"
        elif self.consume('either'):
            self.skip_whitespace(); self.expect('{')
            parts = []
            while self.pos < len(self.source):
                self.skip_whitespace()
                if self.peek() == '}': break
                parts.append(self.parse_statement())
                self.skip_whitespace()
            self.expect('}')
            return f"(?:{'|'.join(p for p in parts if p)})"
        elif self.consume('ahead'):
            self.skip_whitespace(); self.expect('{')
            inner = self.parse_statements(); self.expect('}')
            return f"(?={inner})"
        elif self.consume('behind'):
            self.skip_whitespace(); self.expect('{')
            inner = self.parse_statements(); self.expect('}')
            return f"(?<={inner})"
        elif self.consume('not'):
            self.skip_whitespace()
            if self.consume('ahead'):
                self.skip_whitespace(); self.expect('{')
                inner = self.parse_statements(); self.expect('}')
                return f"(?!{inner})"
            elif self.consume('behind'):
                self.skip_whitespace(); self.expect('{')
                inner = self.parse_statements(); self.expect('}')
                return f"(?<!{inner})"
            elif self.peek() == '<':
                symbol = self.parse_symbol()
                negated = { r'\d': r'\D', r'\s': r'\S', r'\w': r'\W', r'\b': r'\B', ' ': '[^ ]',
                            r'\n': r'[^\n]', r'\t': r'[^\t]', r'\r': r'[^\r]', r'\v': r'[^\v]', r'\f': r'[^\f]',
                            '[a-zA-Z]': '[^a-zA-Z]', '[a-zA-Z0-9]': '[^a-zA-Z0-9]' }
                if symbol == '.': self.error("negative char not allowed")
                if symbol == '^': self.error("negative start not allowed")
                if symbol == '$': self.error("negative end not allowed")
                return negated[symbol]
            else: self.error("expected amount, class_content, or assertion_type")
        elif self.peek() == '.':
            if in_quantifier: self.error("unexpected variable invocation in quantifier")
            start = self.pos
            while self.pos < len(self.source) and not self.source[self.pos].isspace() and self.source[self.pos] != ';':
                self.pos += 1
            name = self.source[start:self.pos]
            if name not in self.variables: self.error("usage of an uninitialized variable")
            return self.variables[name]
        else: self.error("expected root")

    def parse_statement(self):
        self.skip_whitespace()
        if self.consume('let'):
            self.skip_whitespace()
            if self.peek() != '.': self.error("expected variable name")
            start = self.pos
            while self.pos < len(self.source) and not self.source[self.pos].isspace() and self.source[self.pos] != '=':
                self.pos += 1
            name = self.source[start:self.pos]; self.skip_whitespace(); self.expect('='); self.skip_whitespace(); self.expect('{')
            inner = self.parse_statements(); self.expect('}'); self.variables[name] = inner
            return ""

        saved_pos = self.pos
        q = self.parse_quantifier()
        if q:
            self.skip_whitespace()
            if self.consume('of'):
                expr = self.parse_expression(in_quantifier=True)
                if not (expr.endswith(')') or expr.endswith(']')): self.skip_whitespace(); self.expect(';')
                return f"{expr}{q}"
            self.pos = saved_pos

        expr = self.parse_expression()
        if not (expr.endswith(')') or expr.endswith(']')): self.skip_whitespace(); self.expect(';')
        return expr

    def parse_quantifier(self):
        self.skip_whitespace()
        if self.consume('some'): return '+'
        if self.consume('any'): return '*'
        if self.consume('option'): return '?'
        start = self.pos
        while self.pos < len(self.source) and self.source[self.pos].isdigit(): self.pos += 1
        if self.pos > start:
            num1 = self.source[start:self.pos]; self.skip_whitespace()
            if self.consume('to'):
                self.skip_whitespace(); start2 = self.pos
                while self.pos < len(self.source) and self.source[self.pos].isdigit(): self.pos += 1
                if self.pos > start2: return f"{{{num1},{self.source[start2:self.pos]}}}"
                else: self.error("expected amount")
            return f"{{{num1}}}"
        return None

    def parse_statements(self):
        res = ""
        while self.pos < len(self.source):
            self.skip_whitespace()
            if self.pos >= len(self.source) or self.peek() == '}': break
            res += self.parse_statement()
        return res

