            while self.pos < len(self.source) and (self.source[self.pos].isalnum() or self.source[self.pos] == '_'): self.pos += 1
            name = self.source[start:self.pos]
            if name not in self.variables: self.error("usage of an uninitialized variable")
            return self.variables[name]
        else: self.error("expected root")

    def parse_statement(self):
        self.skip_whitespace()
        if self.consume('let'):
            self.skip_whitespace(); start = self.pos
            while self.pos < len(self.source) and not self.source[self.pos].isspace() and self.source[self.pos] != '=': self.pos += 1
            name = self.source[start:self.pos]; self.skip_whitespace(); self.expect('='); self.skip_whitespace(); self.expect('{')
            inner = self.parse_statements(); self.expect('}'); self.variables[name] = inner; return ""
        saved_pos = self.pos
        q = self.parse_quantifier()
        if q:
            self.skip_whitespace()
            if self.consume('of'):
                expr = self.parse_expression(in_quantifier=True)
                if self.source[self.pos-1] != '}': self.skip_whitespace(); self.expect(';')
                return f"{expr}{q}"
            self.pos = saved_pos
        expr = self.parse_expression()
        if self.source[self.pos-1] != '}': self.skip_whitespace(); self.expect(';')
        return expr

    def parse_quantifier(self):
        self.skip_whitespace()
        if self.consume('some'): return '+'
        if self.consume('any'): return '*'
        if self.consume('option'): return '?'
        start = self.pos
        while self.pos < len(self.source) and self.source[self.pos].isdigit(): self.pos += 1
        if self.pos > start:
            num1 = self.source[start:self.pos]; self.skip_whitespace()
            if self.consume('to'):
                self.skip_whitespace(); start2 = self.pos
                while self.pos < len(self.source) and self.source[self.pos].isdigit(): self.pos += 1
                if self.pos > start2: return f"{{{num1},{self.source[start2:self.pos]}}}"
                else: self.error("expected amount")
            return f"{{{num1}}}"
        return None

    def parse_statements(self):
        res = ""
        while self.pos < len(self.source):
            self.skip_whitespace()
            if self.pos >= len(self.source) or self.peek() == '}': break
            res += self.parse_statement()
        return res

def main():
    parser = argparse.ArgumentParser(); parser.add_argument("input_file", nargs="?", default="-")
    parser.add_argument("-o", "--output"); parser.add_argument("-n", "--no-color", action="store_true")
    parser.add_argument("-r", "--repl", action="store_true"); parser.add_argument("-t", "--test")
    parser.add_argument("-f", "--test-file"); parser.add_argument("-V", "--version", action="store_true")
    parser.add_argument("--generate-completions"); args = parser.parse_args()
    if args.version: print("melody_cli 0.20.0"); return
    if args.input_file == "-": source = sys.stdin.read()
    else:
        try:
            with open(args.input_file, "r") as f: source = f.read()
        except: sys.exit(1)
    p = MelodyParser(source); regex = p.parse_statements()
    if args.test:
        if re.search(regex, args.test): print(f"'{args.test}' matched")
        else: print(f"'{args.test}' did not match")
    elif args.test_file:
        try:
            with open(args.test_file, "r") as f: content = f.read()
            if re.search(regex, content): print(f"'{args.test_file}' matched")
            else: print(f"'{args.test_file}' did not match")
        except: sys.exit(1)
    elif args.output:
        with open(args.output, "w") as f: f.write(regex)
    else: sys.stdout.write(regex + "\n")

if __name__ == "__main__": main()
